html:
{%- set earnings = doc.earnings | rejectattr("do_not_include_in_total") | rejectattr("statistical_component") | list -%}
{%- set deductions = doc.deductions | rejectattr("do_not_include_in_total") | rejectattr("statistical_component") | list -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=doc.currency) }}{%- endmacro -%}

<div class="slip">
	<div class="head">
		<div class="org">{{ doc.company }}</div>
		<div class="title">Salary Slip</div>
		<div class="period">
			{{ frappe.utils.formatdate(doc.start_date, "d MMMM yyyy") }}
			&ndash;
			{{ frappe.utils.formatdate(doc.end_date, "d MMMM yyyy") }}
		</div>
	</div>

	<table class="meta">
		<tr>
			<th>Employee</th><td>{{ doc.employee_name }}</td>
			<th>Employee ID</th><td>{{ doc.employee }}</td>
		</tr>
		<tr>
			<th>Designation</th><td>{{ doc.designation or "&mdash;" }}</td>
			<th>Department</th><td>{{ doc.department or "&mdash;" }}</td>
		</tr>
		<tr>
			<th>Branch</th><td>{{ doc.branch or "&mdash;" }}</td>
			<th>Pay Date</th><td>{{ frappe.utils.formatdate(doc.posting_date, "d MMM yyyy") }}</td>
		</tr>
	</table>

	<div class="days">
		<div class="day-box">
			<span class="k">Period From</span>
			<span class="v">{{ frappe.utils.formatdate(doc.start_date, "d MMM yyyy") }}</span>
		</div>
		<div class="day-box">
			<span class="k">Period To</span>
			<span class="v">{{ frappe.utils.formatdate(doc.end_date, "d MMM yyyy") }}</span>
		</div>
		<div class="day-box">
			<span class="k">Total Working Days</span>
			<span class="v">{{ doc.total_working_days | round | int }}</span>
		</div>
		<div class="day-box hi">
			<span class="k">Days Paid</span>
			<span class="v">{{ doc.payment_days | round | int }}</span>
		</div>
	</div>

	{% if doc.payment_days and doc.total_working_days and doc.payment_days < doc.total_working_days %}
	<p class="prorata">
		Paid for {{ doc.payment_days | round | int }} of
		{{ doc.total_working_days | round | int }} days.
		{%- if doc.leave_without_pay %} Leave without pay: {{ doc.leave_without_pay | round | int }} day(s).{% endif %}
		{%- if doc.absent_days %} Absent: {{ doc.absent_days | round | int }} day(s).{% endif %}
	</p>
	{% endif %}

	<table class="lines">
		<thead>
			<tr><th>Earnings</th><th class="num">Amount</th></tr>
		</thead>
		<tbody>
			{% for row in earnings %}
			<tr><td>{{ row.salary_component }}</td><td class="num">{{ money(row.amount) }}</td></tr>
			{% else %}
			<tr><td colspan="2" class="none">No earnings</td></tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr><th>Gross Pay</th><th class="num">{{ money(doc.gross_pay) }}</th></tr>
		</tfoot>
	</table>

	<table class="lines">
		<thead>
			<tr><th>Deductions</th><th class="num">Amount</th></tr>
		</thead>
		<tbody>
			{% for row in deductions %}
			<tr><td>{{ row.salary_component }}</td><td class="num">{{ money(row.amount) }}</td></tr>
			{% else %}
			<tr><td colspan="2" class="none">No deductions</td></tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr><th>Total Deductions</th><th class="num">{{ money(doc.total_deduction) }}</th></tr>
		</tfoot>
	</table>

	<table class="net">
		<tr>
			<th>Net Pay</th>
			<td class="num">{{ money(doc.rounded_total or doc.net_pay) }}</td>
		</tr>
	</table>

	{% if doc.total_in_words %}
	<p class="words"><span>In words:</span> {{ doc.total_in_words }}</p>
	{% endif %}

	<div class="sign">
		<div class="sig"><span></span>Prepared by</div>
		<div class="sig"><span></span>Approved by</div>
		<div class="sig"><span></span>Received by</div>
	</div>

	<p class="foot">
		This slip shows employee earnings and deductions only. Employer contributions
		are not included.
	</p>
</div>

<style>
	.slip { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; color: #1a1a1a; font-size: 11px; }
	.head { text-align: center; border-bottom: 2px solid #1a1a1a; padding-bottom: 8px; margin-bottom: 14px; }
	.head .org { font-size: 15px; font-weight: 700; letter-spacing: .02em; }
	.head .title { font-size: 12px; text-transform: uppercase; letter-spacing: .18em; margin-top: 3px; }
	.head .period { font-size: 11px; color: #555; margin-top: 3px; }

	table.meta { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
	table.meta th, table.meta td { text-align: left; padding: 3px 6px 3px 0; vertical-align: top; }
	table.meta th { width: 12%; font-weight: 600; color: #666; font-size: 10px; text-transform: uppercase; letter-spacing: .04em; }
	table.meta td { width: 38%; }

	.days { display: table; width: 100%; table-layout: fixed; border-collapse: separate; border-spacing: 6px 0; margin: 0 -6px 12px; }
	.day-box { display: table-cell; border: 1px solid #d5d5d5; padding: 6px 8px; text-align: center; }
	.day-box.hi { background: #f2f2f2; border-color: #1a1a1a; }
	.day-box .k { display: block; font-size: 9px; text-transform: uppercase; letter-spacing: .05em; color: #666; }
	.day-box .v { display: block; font-size: 14px; font-weight: 700; margin-top: 2px; }

	p.prorata { margin: 0 0 12px; font-size: 10px; color: #444; font-style: italic; }

	table.lines { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	table.lines th, table.lines td { padding: 5px 8px; border-bottom: 1px solid #e2e2e2; text-align: left; }
	table.lines thead th { background: #f2f2f2; border-bottom: 1px solid #bbb; font-size: 10px; text-transform: uppercase; letter-spacing: .05em; }
	table.lines tfoot th { border-top: 1px solid #1a1a1a; border-bottom: none; font-weight: 700; }
	table.lines .num, table.net .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
	table.lines .none { color: #888; font-style: italic; }

	table.net { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	table.net th, table.net td { padding: 8px; background: #1a1a1a; color: #fff; font-size: 13px; font-weight: 700; text-align: left; }

	p.words { font-size: 10px; margin: 0 0 20px; }
	p.words span { color: #666; text-transform: uppercase; letter-spacing: .04em; font-size: 9px; }

	.sign { display: table; width: 100%; table-layout: fixed; border-spacing: 14px 0; margin: 0 -14px; }
	.sig { display: table-cell; font-size: 10px; color: #444; text-align: center; }
	.sig span { display: block; border-bottom: 1px solid #999; height: 30px; margin-bottom: 4px; }

	p.foot { margin-top: 18px; padding-top: 6px; border-top: 1px solid #e2e2e2; font-size: 9px; color: #777; text-align: center; }
</style>
